<script setup>import {ref} from 'vue';import {LayoutDashboard,FileText,PenSquare,PlaySquare,BarChart3,Users,CreditCard,Image,Settings,TrendingUp,Eye,Clock,MoreHorizontal,Plus,Search} from 'lucide-vue-next';const active=ref('Dashboard');const menu=[['Dashboard',LayoutDashboard],['Stories',FileText],['Create Story',PenSquare],['Shorts',PlaySquare],['Polls',BarChart3],['Audience',Users],['Subscriptions',CreditCard],['Media Library',Image],['Settings',Settings]];const stories=[['City transport plan: what changes next month','Published','India','184K'],['Markets rally as technology stocks gain','Published','Business','126K'],['Five AI tools changing everyday work','Scheduled','Tech','—'],['Championship preview: players to watch','Draft','Sports','—']];</script><template><div class="admin-shell"><aside class="admin-side"><div class="brand admin-brand"><span class="brand-mark">P</span><span><strong>PULSE</strong><small>NEWSROOM</small></span></div><button v-for="m in menu" :class="{active:active===m[0]}" @click="active=m[0]"><component :is="m[1]"/>{{m[0]}}</button><div class="admin-user"><span>GC</span><div><b>News Admin</b><small>Editor in Chief</small></div></div></aside><section class="admin-main"><header class="admin-head"><div><small>NEWSROOM / {{active.toUpperCase()}}</small><h1>{{active}}</h1></div><div><button class="admin-search"><Search/> Search</button><button class="new-story"><Plus/> New story</button></div></header><div v-if="active==='Dashboard'"><div class="metric-grid"><article><span>STORY VIEWS</span><h2>2.84M</h2><small class="up"><TrendingUp/> +18.2% this week</small></article><article><span>UNIQUE READERS</span><h2>864K</h2><small class="up">+12.4% this week</small></article><article><span>AVG. READ TIME</span><h2>3m 42s</h2><small>+24 sec vs last week</small></article><article><span>ACTIVE SUBSCRIBERS</span><h2>48,219</h2><small class="up">+1,842 this month</small></article></div><div class="admin-grid"><div class="chart-card"><div class="card-head"><div><b>Audience overview</b><small>Views over the last 7 days</small></div><select><option>Last 7 days</option></select></div><div class="fake-chart"><div v-for="h in [42,55,48,68,61,82,74]" :style="{height:h+'%'}"></div></div><div class="chart-labels"><span v-for="d in ['Mon','Tue','Wed','Thu','Fri','Sat','Sun']">{{d}}</span></div></div><div class="chart-card"><div class="card-head"><div><b>Traffic sources</b><small>Where readers come from</small></div></div><div class="traffic"><div v-for="x in [['Direct',38],['Search',27],['Social',21],['Notifications',9],['Other',5]]"><span>{{x[0]}}</span><i><b :style="{width:x[1]+'%'}"></b></i><strong>{{x[1]}}%</strong></div></div></div></div><div class="story-table"><div class="card-head"><div><b>Recent stories</b><small>Latest newsroom activity</small></div><a>View all stories</a></div><table><thead><tr><th>Story</th><th>Status</th><th>Section</th><th><Eye/> Views</th><th></th></tr></thead><tbody><tr v-for="s in stories"><td><b>{{s[0]}}</b><small><Clock/> Updated recently</small></td><td><span :class="['status',s[1].toLowerCase()]">{{s[1]}}</span></td><td>{{s[2]}}</td><td>{{s[3]}}</td><td><MoreHorizontal/></td></tr></tbody></table></div></div><div v-else class="module-placeholder"><component :is="menu.find(m=>m[0]===active)?.[1]"/><h2>{{active}} workspace</h2><p>This module is ready for Supabase-backed CRUD, filters, permissions and realtime updates.</p><button class="new-story"><Plus/> Create / Add</button></div></section></div></template>